import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"Observability real-driver testing — 8 axis × 4 provider = 32 cell grid + real-driver env-gate (SSOT)","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/observability-real-driver-testing.md","filePath":"concepts/observability-real-driver-testing.md"}'),d={name:"concepts/observability-real-driver-testing.md"};function i(s,e,c,l,n,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="observability-real-driver-testing-—-8-axis-×-4-provider-32-cell-grid-real-driver-env-gate-ssot" tabindex="-1">Observability real-driver testing — 8 axis × 4 provider = 32 cell grid + real-driver env-gate (SSOT) <a class="header-anchor" href="#observability-real-driver-testing-—-8-axis-×-4-provider-32-cell-grid-real-driver-env-gate-ssot" aria-label="Permalink to &quot;Observability real-driver testing — 8 axis × 4 provider = 32 cell grid + real-driver env-gate (SSOT)&quot;">​</a></h1><p>kiwa&#39;s v1.17 observability work covered the <strong>4 base axes</strong> (dashboard mock / alert rule mock / trace flame mock / log correlation mock) as unified mocks for Grafana OSS + Prometheus + Loki + OpenTelemetry Collector — the <code>docs/concepts/observability-v2-testing.md</code> doc is the SSOT for those 4 axes. v1.35 adds <strong>8 advanced axes on top of that base</strong> — the ones production observability stacks hit once their mock-only Grafana suite is green but real Prometheus recording rules, real Tempo exemplar links, real Pyroscope flame graphs, and real Alertmanager silences start showing up in on-call rotation post-mortems. This concept doc is the SSOT for those 8 axes; the tutorials (70-72) and dogfood app new / v2 (v1.35-2/3/4) are the concrete implementations.</p><h2 id="the-8-axis-grid" tabindex="-1">The 8-axis grid <a class="header-anchor" href="#the-8-axis-grid" aria-label="Permalink to &quot;The 8-axis grid&quot;">​</a></h2><p>The 8 advanced axes are cover-oriented — each one names a real-world failure surface every non-trivial production observability stack hits within the first quarter.</p><table tabindex="0"><thead><tr><th>Axis</th><th>Real-world failure it catches</th><th>v2.1 API</th></tr></thead><tbody><tr><td>SLO</td><td>&quot;The SLO recording rule fired an MWMB alert at 14.4× burn but nobody paged because the multi-window path was single-window on the day of the outage&quot; (no state machine, no threshold enumeration)</td><td><code>startSLO</code> / <code>openSLOWindow</code> / <code>recordRequests</code> / <code>computeErrorBudget</code> / <code>evaluateBurnRate</code> / <code>fireMultiWindowMultiBurnRateAlert</code></td></tr><tr><td>RED/USE</td><td>&quot;The p95 dashboard showed green but the RED/USE panel had a stale saturation number because the aggregator dropped a sample&quot; (no per-signal ledger, no four-golden-signal invariant)</td><td><code>startRedUse</code> / <code>recordRequestRate</code> / <code>recordErrors</code> / <code>recordDuration</code> / <code>recordSaturation</code> / <code>computeFourGoldenSignals</code></td></tr><tr><td>Exemplar</td><td>&quot;The p99 latency panel showed red but clicking through the exemplar dot went nowhere because the trace was already dropped by tail-sampling&quot; (no exemplar chain, no bidirectional resolve)</td><td><code>startExemplarSession</code> / <code>recordExemplarMetric</code> / <code>attachTraceToMetric</code> / <code>resolveMetricToTrace</code> / <code>resolveTraceToMetric</code></td></tr><tr><td>OTel advanced</td><td>&quot;The Collector&#39;s batch processor stalled silently because a broken config set <code>send_batch_size = 0</code>; no baggage propagation error surfaced because the header was silently dropped&quot; (no batch invariant, no baggage / W3C strict format check)</td><td><code>startOtelAdvanced</code> / <code>enqueueSpan</code> / <code>flushBatch</code> / <code>detectResource</code> / <code>propagateBaggage</code> / <code>extractW3CContext</code></td></tr><tr><td>Log-correlation advanced</td><td>&quot;The LogQL query matched a log line but the PromQL join failed because the trace_id in the log was hex-only and the metric label was hex-with-prefix&quot; (no join contract, no correlation index)</td><td><code>startLogCorrelationAdvanced</code> / <code>emitStructuredLog</code> / <code>joinTraceIds</code> / <code>joinLogQLAndPromQL</code> / <code>buildCorrelationIndex</code></td></tr><tr><td>Alert-routing advanced</td><td>&quot;The silence fired but the inhibit rule leaked because the label matcher was inverted; the escalation chain skipped step 2 because the on-call rotation was empty&quot; (no matcher unit test, no escalation-step invariant)</td><td><code>startAlertRoutingAdvanced</code> / <code>applySilence</code> / <code>applyInhibit</code> / <code>setEscalationChain</code> / <code>advanceEscalation</code> / <code>pageOncall</code> / <code>isSilenced</code></td></tr><tr><td>Profiling</td><td>&quot;The Pyroscope flame graph rendered but the hottest frame was 3× off because the eBPF profiler dropped every third sample under load; the depth-first flatten reversed sibling order on the panel&quot; (no root-invariant, no flatten contract)</td><td><code>startProfiling</code> / <code>sampleCpu</code> / <code>sampleMemory</code> / <code>sampleOffCpu</code> / <code>buildFlameGraph</code> / <code>flattenFlameGraph</code></td></tr><tr><td>Cardinality</td><td>&quot;The Prometheus HEAD blew past 5 M series overnight because a request-id label was un-reduced; the histogram bucket boundaries drifted after a config rewrite and the p99 line broke silently&quot; (no series-fingerprint scan, no bucket contract)</td><td><code>startCardinalitySession</code> / <code>scanSeries</code> / <code>detectHighCardinality</code> / <code>reduceLabel</code> / <code>bucketHistogram</code></td></tr></tbody></table><p>Each axis has 3 shapes — a mock-only path (fast inner loop, ms scale), a real-driver path (<code>KIWA_MODE=real</code> + real Grafana OSS / Prometheus / Loki / OpenTelemetry Collector / Pyroscope, seconds scale), and a fidelity assertion that the two produce the same output. Tutorial 70 covers the SLO axis end-to-end (open window → budget → burn → MWMB alert), tutorial 71 covers the exemplar + OTel-advanced axes (record → attach → m2t / t2m → batch flush → baggage → W3C context), tutorial 72 covers the profiling axis end-to-end (cpu / memory / off-cpu sample → flame graph build → flatten for panel render).</p><h2 id="the-4-provider-×-8-axis-32-cell-grid" tabindex="-1">The 4-provider × 8-axis = 32 cell grid <a class="header-anchor" href="#the-4-provider-×-8-axis-32-cell-grid" aria-label="Permalink to &quot;The 4-provider × 8-axis = 32 cell grid&quot;">​</a></h2><p>Every provider covers every axis. The mock shapes are provider-neutral (the API surface is the same across Grafana OSS + Prometheus + Loki + OpenTelemetry Collector), the emitted event dialects are provider-specific (<code>grafana.slo.window.open</code> vs <code>prom.slo.window.open</code> vs <code>loki.slo.window</code> vs <code>otel.slo.window</code>), and the fidelity harness reports the coverage explicitly.</p><table tabindex="0"><thead><tr><th>Provider</th><th>SLO</th><th>RED/USE</th><th>Exemplar</th><th>OTel</th><th>LogCorr</th><th>AlertRt</th><th>Profiling</th><th>Cardinality</th></tr></thead><tbody><tr><td>Grafana OSS</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>Prometheus</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>Loki</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>OpenTelemetry Collector</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr></tbody></table><p>The v1.35 observability grid is fully covered — every provider implements every axis because the semantics are runtime-agnostic. That is what makes cross-provider reuse (a session that runs under Grafana OSS + Prometheus + Loki + OpenTelemetry Collector without change) even possible.</p><h3 id="why-the-observability-grid-is-fully-covered" tabindex="-1">Why the observability grid is fully covered <a class="header-anchor" href="#why-the-observability-grid-is-fully-covered" aria-label="Permalink to &quot;Why the observability grid is fully covered&quot;">​</a></h3><p>Grafana OSS + Prometheus + Loki + OpenTelemetry Collector converged on the same neutral events at the OTLP + PromQL + LogQL + trace-context layer — the &quot;record a metric with a trace_id&quot; primitive is the same shape across all 4 providers, even though the wire encodings differ. The <code>providerEventName(target, neutralEvent)</code> mapping table is the single point where the 4 dialects diverge; everything upstream stays neutral. The v1.35 fidelity grid at 32/32 = 100 % implemented reflects that convergence at the OpenTelemetry wire format level.</p><h2 id="the-kiwa-mode-real-env-gate-contract" tabindex="-1">The <code>KIWA_MODE=real</code> env-gate contract <a class="header-anchor" href="#the-kiwa-mode-real-env-gate-contract" aria-label="Permalink to &quot;The `KIWA_MODE=real` env-gate contract&quot;">​</a></h2><p><code>skipUnlessReal(env)</code> returns <code>{ skip: false, reason: &#39;KIWA_MODE=real detected&#39; }</code> when <code>env.KIWA_MODE === &#39;real&#39;</code> and <code>{ skip: true, reason: &#39;KIWA_MODE!=real — skip real-driver tests (mock semantics apply)&#39; }</code> otherwise. A test that respects the contract combines the gate with a required-env presence check — the dogfood apps use this at each <code>describe.skipIf(gate.skip || envMissing.length &gt; 0)</code> block.</p><p>Per-axis env mapping.</p><ul><li><strong>SLO dogfood</strong> → <code>PROMETHEUS_URL</code> + <code>GRAFANA_URL</code> (Prometheus recording rule + Grafana panel query)</li><li><strong>RED/USE dogfood</strong> → <code>PROMETHEUS_URL</code> + <code>GRAFANA_URL</code> (same pair, different recording rules)</li><li><strong>OTel exemplar dogfood</strong> → <code>OTEL_COLLECTOR_URL</code> + <code>TEMPO_URL</code> (OpenTelemetry Collector OTLP + Grafana Tempo trace fetch)</li><li><strong>OTel-advanced dogfood</strong> → <code>OTEL_COLLECTOR_URL</code> (Collector batch + resource + baggage propagation)</li><li><strong>Log-correlation-advanced dogfood</strong> → <code>LOKI_URL</code> + <code>PROMETHEUS_URL</code> (LogQL + PromQL join)</li><li><strong>Alert-routing-advanced dogfood</strong> → <code>GRAFANA_URL</code> + <code>ALERTMANAGER_URL</code> (silence + inhibit + escalation route)</li><li><strong>Profiling dogfood</strong> → <code>PYROSCOPE_URL</code> (flame graph fetch)</li><li><strong>Cardinality dogfood</strong> → <code>PROMETHEUS_URL</code> (series count + label-value query)</li></ul><p>A test that respects the contract runs the mock path unconditionally and the real-driver path only when both <code>KIWA_MODE=real</code> and the required env are present. That means CI stays cheap by default (mock only, ms scale), the nightly job flips <code>KIWA_MODE=real</code> + the required <code>_URL</code> envs, and the fidelity harness ties the two together.</p><p>Absent env means silently fall back to mock mode — the test still runs, the real-driver assertions get skipped. Absent <code>KIWA_MODE</code> means fall back to mock. An invalid <code>KIWA_MODE</code> value (anything other than <code>real</code>) also falls back to mock so a typo does not break tests.</p><h2 id="the-dogfood-app-new-v2-pattern" tabindex="-1">The dogfood app new / v2 pattern <a class="header-anchor" href="#the-dogfood-app-new-v2-pattern" aria-label="Permalink to &quot;The dogfood app new / v2 pattern&quot;">​</a></h2><p>The 3 dogfood apps (v1.35-2/3/4) each expose a <code>pnpm test:real</code> command that flips <code>KIWA_MODE=real</code> and routes through the real provider stack.</p><ul><li><code>examples/dogfood-observability-slo-app</code> v2 — Grafana OSS + Prometheus + Alertmanager stack + docker-compose backend + <code>pnpm test:real</code> that walks the SLO burn-rate flow (open window → record requests → compute budget → evaluate burn → fire multi-window alert against a real Alertmanager silence route).</li><li><code>examples/dogfood-otel-exemplar-app</code> v2 — OpenTelemetry Collector + Grafana Tempo stack + docker-compose backend + <code>pnpm test:real</code> that walks the exemplar chain (record metric → attach trace → resolve m2t → resolve t2m → flush batch → propagate baggage → extract W3C context) against real OTLP + Tempo endpoints.</li><li><code>examples/dogfood-profiling-app</code> new — Grafana Pyroscope + eBPF profiler + docker-compose backend + <code>pnpm test:real</code> that walks the profiling flow (start session → sample cpu → sample memory → sample off-cpu → build flame graph → flatten for panel render) against a real Pyroscope endpoint.</li></ul><p>The pattern each new / v2 app follows.</p><ol><li>Keep the mock-only path (<code>pnpm test</code>) green — the fast inner loop stays sub-second.</li><li>Add a <code>pnpm test:e2e</code> command that spins the docker-compose stack (Grafana + Prometheus + Loki + OpenTelemetry Collector + Alertmanager + Tempo + Pyroscope, subset per app) and walks the real query flow.</li><li>Add a <code>pnpm test:real</code> command that requires the axis-specific <code>_URL</code> env(s) and routes through the real provider endpoint.</li><li>Run the same fidelity-harness assertions against the real driver; failure means &quot;the mock diverged from real provider behavior&quot; — the mock gets the fix.</li><li>Emit a <code>quality-report/fidelity-latest.md</code> + <code>.json</code> that the v1.29 3-layer defensive structure (release-invariants + docs-e2e + release-smoke) picks up on merge.</li></ol><h2 id="the-not-implemented-failure-mode" tabindex="-1">The <code>not-implemented</code> failure mode <a class="header-anchor" href="#the-not-implemented-failure-mode" aria-label="Permalink to &quot;The `not-implemented` failure mode&quot;">​</a></h2><p>If the fidelity harness has a <code>planned</code> cell, the corresponding tutorial + dogfood + snippet-validation-test trio does not exist yet. The 32-cell grid at v1.35 has 0 <code>planned</code> cells — every intended cell is <code>implemented</code>. When a future milestone adds a 9th axis (e.g., <code>openslo</code> or <code>pyroscope-flame-diff</code>), it will start as <code>planned</code> for all 4 providers, then transition to <code>implemented</code> for the ones that cover it as the milestone lands its tutorial + dogfood + snippet test.</p><h2 id="how-this-ties-into-the-13-axis-release-gate" tabindex="-1">How this ties into the 13-axis release gate <a class="header-anchor" href="#how-this-ties-into-the-13-axis-release-gate" aria-label="Permalink to &quot;How this ties into the 13-axis release gate&quot;">​</a></h2><p>v1.35 does not add a 14th release-gate axis. The 8 advanced observability axes gate the observability package&#39;s own tests (via <code>pnpm --filter @kiwa-lab/observability test</code>) but do not surface as a per-package <code>@kiwa-lab/quality-metrics</code> axis. The reasoning — the fidelity harness is provider-shape-specific, and a package that does not export to Grafana OSS / Prometheus / Loki / OpenTelemetry Collector has nothing to assert on. When a future milestone adds an <code>observability.fidelity</code> axis that describes &quot;which observability providers this package&#39;s tests hit,&quot; it will slot into the 13-axis release gate as the 14th; v1.35 keeps the axis count at 13.</p><h2 id="ssot-boundaries" tabindex="-1">SSOT boundaries <a class="header-anchor" href="#ssot-boundaries" aria-label="Permalink to &quot;SSOT boundaries&quot;">​</a></h2><ul><li>The 4 base observability axes (dashboard / alert / trace flame / log correlation) live in <code>docs/concepts/observability-v2-testing.md</code>. v1.35 does not modify that doc.</li><li>The 8 advanced observability axes live in this doc. Tutorials 70-72 and the migration guide (v1.34 → v1.35) link back here for the axis SSOT.</li><li>The 4-provider × 8-axis grid is the harness&#39;s data structure. The <code>collectFidelityCoverage()</code> implementation in <code>packages/observability/src/semantics/fidelity.ts</code> is the code SSOT — this doc&#39;s grid table is derived from that code.</li><li>The <code>KIWA_MODE=real</code> env-gate contract is shared with the v1.22 real-driver testing tutorial (auth adapters + Keycloak), the v1.31 streaming real-driver concept doc, the v1.32 database real-driver concept doc, the v1.33 payment real-driver concept doc, and the v1.34 frontend real-driver concept doc. All five use the same <code>skipUnlessReal(env)</code> pattern; the observability axes just add provider <code>_URL</code> envs (<code>PROMETHEUS_URL</code> / <code>GRAFANA_URL</code> / <code>LOKI_URL</code> / <code>OTEL_COLLECTOR_URL</code> / <code>TEMPO_URL</code> / <code>PYROSCOPE_URL</code> / <code>ALERTMANAGER_URL</code>) instead of provider-specific <code>_KEY</code> or <code>_BROWSER_READY</code> envs.</li></ul>',29)])])}const u=t(d,[["render",i]]);export{m as __pageData,u as default};
